def is_undulating(n):
    s = str(n)
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1]:
            return False
    digits = [int(d) for d in s]
    for i in range(1, len(digits)):
        if (digits[i-1] < digits[i]) and not (i+1 < len(digits) and digits[i] > digits[i+1]):
            return False
        elif (digits[i-1] > digits[i]) and not (i+1 < len(digits) and digits[i] < digits[i+1]):
            return False
    return True

